package com.bank.dupfinder;

import java.util.*;
import java.util.logging.*;

public class DuplicateDemo {
    private static final Logger log = Logger.getLogger("DupFinder");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> amounts = List.of(5000, 8000, 5000, 12000, 8000, 8000);
        DuplicateFinder finder = new DuplicateFinder();

        log.info(() -> "Duplicates: " + finder.duplicates(amounts));
    }
}

// ─── Would be in service/DuplicateFinder.java ───
class DuplicateFinder {
    List<Integer> duplicates(List<Integer> nums) {
        Map<Integer, Long> counts = nums.stream()
            .collect(java.util.stream.Collectors.groupingBy(
                n -> n, LinkedHashMap::new,
                java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
            .filter(e -> e.getValue() > 1L)       // appears more than once
            .map(Map.Entry::getKey)
            .toList();
    }
}
